-- Masarak GLOBAL — global09: enrich universities (students, languages, intl%, acceptance, description).
-- 222 rows, web-researched (Wikipedia/official). Volatile fields null where not reliably published.
update universities_global u set
  student_population   = coalesce(v.students, u.student_population),
  languages            = v.langs,
  intl_students_pct    = coalesce(v.intl, u.intl_students_pct),
  acceptance_rate      = coalesce(v.acc, u.acceptance_rate),
  description_short_ar = v.descr,
  last_verified_at     = now()
